export type FieldOrientation = "row" | "column";

export interface FieldDescriptor {
  label: string;
  name: string;
  value: string;
  orientation?: FieldOrientation;
  kind?: string;
  issues?: readonly string[];
  extraClass?: string;
}

export interface FieldPresentation {
  label: string;
  name: string;
  value: string;
  orientation: FieldOrientation;
  kind: string;
  inputClass: string;
  issues: string[];
}

export function makeFieldPresentation(input: FieldDescriptor): FieldPresentation {
  if (typeof input !== "object" || input === null || Array.isArray(input)) {
    throw new TypeError("input must be an object");
  }
  if (typeof input.name !== "string" || input.name.trim() === "") {
    throw new TypeError("name must be nonblank");
  }
  const orientation = input.orientation ?? "column";
  if (orientation !== "row" && orientation !== "column") {
    throw new TypeError("invalid orientation");
  }
  if (input.issues !== undefined && !Array.isArray(input.issues)) {
    throw new TypeError("issues must be an array");
  }
  const issues = input.issues === undefined ? [] : Array.from(input.issues);
  if (issues.some((issue) => typeof issue !== "string")) {
    throw new TypeError("issues must contain strings");
  }
  const suffix = typeof input.extraClass === "string" ? input.extraClass.trim() : "";
  return {
    label: input.label,
    name: input.name,
    value: input.value,
    orientation,
    kind: input.kind ?? "text",
    inputClass: suffix === "" ? "field-input" : suffix,
    issues,
  };
}

