import { makeFieldPresentation } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), `${message}: ${JSON.stringify(actual)}`);
}
function throwsTypeError(action: () => void, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof TypeError, message);
}

const minimal = makeFieldPresentation({ label: ' Label ', name: 'field', value: ' value ' });
equal(minimal, {
  label: ' Label ', name: 'field', value: ' value ', orientation: 'column',
  kind: 'text', inputClass: 'field-input', issues: [],
}, 'defaults and exact preservation');

const issues = ['first', 'second'];
const descriptor: any = {
  label: 'Age', name: 'age', value: 42, orientation: 'row', kind: 'number',
  issues, extraClass: '  wide highlighted  ',
};
const presented = makeFieldPresentation(descriptor);
equal(presented, {
  label: 'Age', name: 'age', value: 42, orientation: 'row', kind: 'number',
  inputClass: 'field-input wide highlighted', issues: ['first', 'second'],
}, 'explicit normalization');
assert(presented.issues !== issues, 'issues copied');
issues.push('later');
descriptor.label = 'Changed';
assert(presented.issues.length === 2 && presented.label === 'Age', 'input not retained');

assert(makeFieldPresentation({ label: '', name: 'x', value: '', extraClass: '   ' }).inputClass === 'field-input', 'blank class ignored');
throwsTypeError(() => makeFieldPresentation({ label: 'x', name: '   ', value: '' }), 'blank name rejected');
throwsTypeError(() => makeFieldPresentation({ label: 'x', name: 'x', value: '', orientation: 'grid' as any }), 'orientation rejected');
throwsTypeError(() => makeFieldPresentation({ label: 'x', name: 'x', value: '', issues: 'bad' as any }), 'non-array issues rejected');
throwsTypeError(() => makeFieldPresentation({ label: 'x', name: 'x', value: '', issues: ['ok', 2] as any }), 'non-string issue rejected');

